section .text
; precedence_lookup(token_kind, fixity) -> RAX=record or zero.  On success,
; EDX=left BP, ECX=right BP, R8D=associativity, R9D=family, R10D=flags.
NEBOC_ABI_FUNCTION neboc_operator_precedence_lookup
 lea rax,[rel current_precedence]
 mov r11d,NEBOC_OPERATOR_PRECEDENCE_ENTRY_COUNT
.loop:
 cmp [rax+NEBOC_OPERATOR_PRECEDENCE_TOKEN_OFFSET],rdi
 jne .next
 cmp [rax+NEBOC_OPERATOR_PRECEDENCE_FIXITY_OFFSET],rsi
 je .found
.next:
 add rax,NEBOC_OPERATOR_PRECEDENCE_ENTRY_SIZE
 dec r11d
 jnz .loop
 xor eax,eax
 xor edx,edx
 xor ecx,ecx
 xor r8d,r8d
 xor r9d,r9d
 xor r10d,r10d
 ret
.found:
 mov edx,[rax+NEBOC_OPERATOR_PRECEDENCE_LEFT_BP_OFFSET]
 mov ecx,[rax+NEBOC_OPERATOR_PRECEDENCE_RIGHT_BP_OFFSET]
 mov r8d,[rax+NEBOC_OPERATOR_PRECEDENCE_ASSOC_OFFSET]
 mov r9d,[rax+NEBOC_OPERATOR_PRECEDENCE_FAMILY_OFFSET]
 mov r10d,[rax+NEBOC_OPERATOR_PRECEDENCE_FLAGS_OFFSET]
 ret

NEBOC_ABI_FUNCTION neboc_operator_precedence_table
 lea rax,[rel current_precedence]
 mov edx,NEBOC_OPERATOR_PRECEDENCE_ENTRY_COUNT
 mov ecx,NEBOC_OPERATOR_PRECEDENCE_ENTRY_SIZE
 mov r8d,NEBOC_OPERATOR_PRECEDENCE_SCHEMA_VERSION
 ret

; FixitySpec is the same immutable record as the canonical PrecedenceTable.
NEBOC_ABI_FUNCTION neboc_fixity_spec_lookup
 jmp neboc_operator_precedence_lookup

section .note.GNU-stack noalloc noexec nowrite progbits
